import {test} from 'node:test';import assert from 'node:assert/strict';import {mkdtempSync,rmSync,writeFileSync,readFileSync} from 'node:fs';import {join} from 'node:path';import {DatabaseSync} from 'node:sqlite';import {createChatService} from '../../chat-service.mjs';import {writeAccountSession} from '@cpclaw/desktop-host/account-session';
export function fixture(t,runServiceLoop,executeService=async()=>({ok:true})){const root=mkdtempSync('/tmp/cpclaw-unified-'),events=[],calls=[];writeAccountSession(root,{schemaVersion:1,employeeId:'kernel-user',sessionId:'fixture',refreshToken:'fixture-refresh'},{makeCurrent:true});writeFileSync(join(root,'desktop-connection.json'),JSON.stringify({platformUrl:'https://fixture.invalid'}));t.mock.method(globalThis,'fetch',async(url,init)=>{calls.push(url);if(url.endsWith('/v1/session/refresh'))return Response.json({employeeId:'kernel-user',sessionId:'fixture',refreshToken:'fixture-refresh',accessToken:'fixture'});if(url.endsWith('/v1/market')){const b=JSON.parse(init.body);if(b.action==='save')return Response.json({ok:true,item:{id:'saved-skill'}});return Response.json({ok:true,items:[],connectors:[]});}throw Error('禁止的模型旁路 '+url);});let service=createChatService(root,e=>events.push(e),{runServiceLoop,executeService});return {root,events,calls,get service(){return service;},restart(){service.stop();service=createChatService(root,e=>events.push(e),{runServiceLoop,executeService});},actor:'kernel-user',create:async()=>{const r=await service.dispatch('chat.create','kernel-user',{});assert(r.ok,JSON.stringify(r));return r.chatId;},send:(chatId,text,requestId='i-'+crypto.randomUUID(),extra={})=>service.dispatch('chat.send','kernel-user',{chatId,text,requestId,...extra}).then(r=>{if(!r.ok)process.stderr.write(JSON.stringify(r)+'\n');return r;}),stop(){service.stop();rmSync(root,{recursive:true,force:true});}};}
